// FUNCTION: BFME2 0x00327287 size=91 name=?GadgetTabControlResizeSubPanes@@YAXPAVGameWindow@@@Z evidence=N:ledger tier=B hypothesis:name:invented
void GadgetTabControlResizeSubPanes(GameWindow *tabControl)
{
	TabControlData *tabData = (TabControlData *)tabControl->winGetUserData();
	int width, height, x, y;
	GadgetTabControlComputeSubPaneSize(tabControl, &width, &height, &x, &y);
	for (int paneIndex = 0; paneIndex < 8; paneIndex++) {
		if (tabData->m_subPanes[paneIndex]) {
			tabData->m_subPanes[paneIndex]->winSetSize(width, height);
			tabData->m_subPanes[paneIndex]->winSetPosition(x, y);
		}
	}
}

// FUNCTION: BFME2 0x003272E2 size=78 name=?GadgetTabControlFixupSubPaneList@@YAXPAVGameWindow@@@Z evidence=N:ledger tier=B hypothesis:K
void GadgetTabControlFixupSubPaneList(GameWindow *tabControl)
{
	TabControlData *tabData = (TabControlData *)tabControl->winGetUserData();
	GameWindow *child = tabControl->winGetChild();
	if (child) {
		while (child->winGetNext())
			child = child->winGetNext();
		if (child) {
			GameWindow **slot = tabData->m_subPanes;
			do {
				*slot = child;
				slot++;
				child = child->winGetPrev();
			} while (child);
		}
	}
}

// FUNCTION: BFME2 0x00327330 size=107 name=?GadgetTabControlSystem@@YA?AW4WindowMsgHandledType@@PAVGameWindow@@III@Z evidence=N:ledger tier=B hypothesis:K
WindowMsgHandledType GadgetTabControlSystem(GameWindow *tabControl, unsigned int msg, unsigned int mData1, unsigned int mData2)
{
	switch (msg) {
	case 1:
		return MSG_HANDLED;
	case 2:
		delete (TabControlData *)tabControl->winGetUserData();
		return MSG_HANDLED;
	case 0x4004:
		GadgetTabControlResizeSubPanes(tabControl);
		GadgetTabControlComputeTabRegion(tabControl);
		return MSG_HANDLED;
	case 0x4008: {
		GameWindow *owner = tabControl->winGetOwner();
		if (owner)
			return TheWindowManager->winSendSystemMsg(owner, 0x4008, mData1, mData2);
	}
	}
	return MSG_IGNORED;
}

